package com.example.pickup;
import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class PickupService {
 private final PickupRepository pickups; private final HandoverRepository handovers; private final CollectorClient collectors; private final WasteClient waste;
 public PickupService(PickupRepository p,HandoverRepository h,CollectorClient c,WasteClient w){pickups=p;handovers=h;collectors=c;waste=w;}
 public List<PickupSchedule> all(){return pickups.findAll();} public PickupSchedule get(long id){return pickups.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Pickup not found: "+id));}
 @Transactional public PickupSchedule create(ScheduleRequest r){Map<String,Object> assignment=collectors.assignment(r.wasteReportId()); if(!"ASSIGNED".equals(assignment.get("status"))||!Objects.equals(((Number)assignment.get("collectorId")).longValue(),r.collectorId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Collector must have an active assignment for this report"); Map<String,Object> report=waste.get(r.wasteReportId()); if(!"ASSIGNED".equals(report.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Waste report must be ASSIGNED before scheduling"); if(pickups.existsByWasteReportIdAndStatusNot(r.wasteReportId(),PickupStatus.CANCELLED))throw new ResponseStatusException(HttpStatus.CONFLICT,"A pickup already exists for this report"); PickupSchedule result=pickups.save(new PickupSchedule(r.wasteReportId(),r.collectorId(),r.pickupDate(),r.pickupTime(),r.pickupAddress(),r.scheduledQuantity())); waste.changeStatus(r.wasteReportId(),Map.of("status","SCHEDULED")); return result;}
 @Transactional public PickupSchedule start(long id){PickupSchedule p=get(id);if(p.getStatus()!=PickupStatus.SCHEDULED)throw conflict(p,"IN_PROGRESS");p.setStatus(PickupStatus.IN_PROGRESS);return pickups.save(p);}
 @Transactional public PickupSchedule complete(long id,double quantity){PickupSchedule p=get(id);if(p.getStatus()!=PickupStatus.IN_PROGRESS)throw conflict(p,"COMPLETED");if(quantity<=0||quantity>p.getScheduledQuantity())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Actual quantity must be positive and cannot exceed scheduled quantity");p.setActualCollectedQuantity(quantity);p.setStatus(PickupStatus.COMPLETED);PickupSchedule result=pickups.save(p);waste.changeStatus(p.getWasteReportId(),Map.of("status","COLLECTED"));return result;}
 @Transactional public RecyclingHandover handover(long id,HandoverRequest r){PickupSchedule p=get(id);if(p.getStatus()!=PickupStatus.COMPLETED)throw conflict(p,"HANDED_OVER");if(r.quantityTransferred()<=0||r.quantityTransferred()>p.getActualCollectedQuantity())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Transferred quantity must be positive and no greater than collected quantity");if(handovers.existsByPickupId(id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Handover already recorded");String category=String.valueOf(waste.get(p.getWasteReportId()).get("wasteCategory"));RecyclingHandover h=handovers.save(new RecyclingHandover(id,r.organizationName(),category,r.quantityTransferred(),LocalDate.now()));p.setStatus(PickupStatus.HANDED_OVER);pickups.save(p);waste.changeStatus(p.getWasteReportId(),Map.of("status","HANDED_OVER"));return h;}
 @Transactional public PickupSchedule cancel(long id){PickupSchedule p=get(id);if(p.getStatus()!=PickupStatus.SCHEDULED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only a scheduled pickup can be cancelled");p.setStatus(PickupStatus.CANCELLED);waste.changeStatus(p.getWasteReportId(),Map.of("status","CANCELLED"));Object assignmentId=collectors.assignment(p.getWasteReportId()).get("id");if(!(assignmentId instanceof Number assignmentNumber))throw new ResponseStatusException(HttpStatus.CONFLICT,"Active assignment response did not contain a valid ID");collectors.changeStatus(assignmentNumber.longValue(),Map.of("status","CANCELLED"));return pickups.save(p);}
 private ResponseStatusException conflict(PickupSchedule p,String next){return new ResponseStatusException(HttpStatus.CONFLICT,"Invalid pickup status transition: "+p.getStatus()+" -> "+next);}
}
record ScheduleRequest(Long wasteReportId,Long collectorId,LocalDate pickupDate,LocalTime pickupTime,String pickupAddress,double scheduledQuantity){} record CompleteRequest(double actualCollectedQuantity){} record HandoverRequest(String organizationName,double quantityTransferred){}
